package message

import (
	"cmp"
	"net/textproto"
	"slices"
	"strings"
	"unicode"

	"github.com/jhillyerd/enmime/v2"
	"github.com/jhillyerd/enmime/v2/dsn"
	"github.com/jhillyerd/enmime/v2/mediatype"
)

// Automation names the kind of mail a program sent rather than a person.
type Automation string

const (
	// NotAutomated is mail that shows no sign of a program sending it.
	NotAutomated Automation = ""
	// AutoGenerated is mail a program sent on its own, such as a notification.
	AutoGenerated Automation = "auto-generated"
	// AutoReply is an automatic answer to earlier mail, such as an out of office note.
	AutoReply Automation = "auto-reply"
	// ListMail is mail sent through a mailing list or in bulk.
	ListMail Automation = "list"
	// Bounce is a delivery report or mail from the system that sends one.
	Bounce Automation = "bounce"
	// AbuseReport is a feedback report in the Abuse Reporting Format.
	AbuseReport Automation = "abuse-report"
	// ReadReceipt is a notice that a recipient displayed earlier mail.
	ReadReceipt Automation = "read-receipt"
)

// Classification is what the fields and parts of a message say about a program sending it.
type Classification struct {
	// Automation is the strongest sign found, NotAutomated when there is none.
	Automation Automation
	// BulkHint reports an X-Auto-Response-Suppress field, which asks receivers not to answer but proves nothing.
	BulkHint bool
	// Report is the delivery report of a bounce, nil when the message carries none or it cannot be read.
	Report *DeliveryReport
}

// DeliveryReport is what a bounce says about the recipients it reports on.
type DeliveryReport struct {
	// Failed lists the recipients the report gave up on, in report order.
	Failed []FailedRecipient
}

// FailedRecipient is one recipient a delivery report gave up on.
type FailedRecipient struct {
	// Email is the final recipient address, lowercased.
	Email string
	// Status is the delivery status code, such as 5.1.1.
	Status string
}

// listFields lists the header fields that only list mail carries.
var listFields = []string{
	"List-Id", "List-Help", "List-Unsubscribe", "List-Subscribe", "List-Post", "List-Owner", "List-Archive",
}

// bulkPrecedences lists the Precedence values of list and bulk mail.
var bulkPrecedences = []string{"bulk", "list", "junk"}

// Classify answers what the fields and parts of m say about a program sending it.
func Classify(m *Message) Classification {
	root := rootOf(m)
	header := root.Header
	senders := localParts(m.From.Email, bareAddress(header.Get("Return-Path")))
	automation, report := reportOf(root)
	return Classification{
		Automation: cmp.Or(
			automation, autoSubmitted(header), autoReplyField(header), bounceSign(header, senders), listSign(header, senders),
		),
		BulkHint: suppressesResponses(header),
		Report:   report,
	}
}

// rootOf answers the top part of m, an empty part when Parse did not build m.
func rootOf(m *Message) *enmime.Part {
	return cmp.Or(m.root, &enmime.Part{})
}

// reportOf answers the kind of the first report part under root and its delivery report when it is a bounce.
func reportOf(root *enmime.Part) (Automation, *DeliveryReport) {
	part := root.BreadthMatchFirst(func(p *enmime.Part) bool { return p.ContentType == "multipart/report" })
	if part == nil {
		return NotAutomated, nil
	}
	_, params, _, _ := mediatype.Parse(part.Header.Get("Content-Type"))
	switch strings.ToLower(params["report-type"]) {
	case "delivery-status":
		return Bounce, deliveryReport(part)
	case "feedback-report":
		return AbuseReport, nil
	case "disposition-notification":
		return ReadReceipt, nil
	}
	return AutoGenerated, nil
}

// deliveryReport answers the failed recipients the report part lists, nil when it cannot be read.
func deliveryReport(part *enmime.Part) *DeliveryReport {
	report, err := dsn.ParseReport(part)
	if err != nil {
		return nil
	}
	delivery := &DeliveryReport{}
	for _, fields := range report.DeliveryStatus.RecipientDSNs {
		if dsn.IsFailed(fields) {
			recipient := fields.Get("Final-Recipient")
			delivery.Failed = append(delivery.Failed, FailedRecipient{
				Email:  bareAddress(recipient[strings.IndexByte(recipient, ';')+1:]),
				Status: first(strings.Fields(fields.Get("Status"))),
			})
		}
	}
	return delivery
}

// autoSubmitted answers the kind the Auto-Submitted field names, NotAutomated when it is missing or no.
func autoSubmitted(header textproto.MIMEHeader) Automation {
	switch strings.ToLower(first(strings.FieldsFunc(header.Get("Auto-Submitted"), endsKeyword))) {
	case "", "no":
		return NotAutomated
	case "auto-replied":
		return AutoReply
	}
	return AutoGenerated
}

// autoReplyField answers AutoReply when header holds a field auto responders add, NotAutomated otherwise.
func autoReplyField(header textproto.MIMEHeader) Automation {
	if header.Values("X-Autoreply") != nil || header.Values("X-Autorespond") != nil {
		return AutoReply
	}
	return NotAutomated
}

// bounceSign answers Bounce for an empty Return-Path or a MAILER-DAEMON sender, NotAutomated otherwise.
func bounceSign(header textproto.MIMEHeader, senders []string) Automation {
	nullPath := header.Values("Return-Path") != nil && bareAddress(header.Get("Return-Path")) == ""
	if nullPath || slices.Contains(senders, "mailer-daemon") {
		return Bounce
	}
	return NotAutomated
}

// listSign answers ListMail for a bulk Precedence, a list field or a list sender, NotAutomated otherwise.
func listSign(header textproto.MIMEHeader, senders []string) Automation {
	precedence := strings.ToLower(strings.TrimSpace(header.Get("Precedence")))
	hasField := func(key string) bool { return header.Values(key) != nil }
	listed := slices.Contains(bulkPrecedences, precedence) || slices.ContainsFunc(listFields, hasField) ||
		slices.ContainsFunc(senders, isListSender)
	if listed {
		return ListMail
	}
	return NotAutomated
}

// suppressesResponses reports whether the X-Auto-Response-Suppress field asks receivers not to answer.
func suppressesResponses(header textproto.MIMEHeader) bool {
	value := strings.TrimSpace(header.Get("X-Auto-Response-Suppress"))
	return value != "" && !strings.EqualFold(value, "none")
}

// localParts answers the part before the @ of each email.
func localParts(emails ...string) []string {
	locals := make([]string, 0, len(emails))
	for _, email := range emails {
		local, _, _ := strings.Cut(email, "@")
		locals = append(locals, local)
	}
	return locals
}

// isListSender reports whether local names the owner or the request address of a list.
func isListSender(local string) bool {
	return strings.HasPrefix(local, "owner-") || strings.HasSuffix(local, "-request")
}

// bareAddress answers address without blanks or angle brackets, lowercased.
func bareAddress(address string) string {
	return normalEmail(strings.Trim(strings.TrimSpace(address), "<>"))
}

// endsKeyword reports whether r ends the keyword opening a structured field.
func endsKeyword(r rune) bool {
	return r == ';' || r == '(' || unicode.IsSpace(r)
}
